INSERT INTO `announcements` (`id`, `title`, `category`, `publish_date`, `author_name`, `content`, `is_pinned`) VALUES (1, 'График проведения аккредитационной экспертизы учебных планов на 2026/2027 учебный год', 'Регламент АНОК', '2026-10-01', 'Начальник Центра АНОК Кузнецов В.П.', 'Центр Аккредитации и независимой оценки качества (АНОК) уведомляет руководителей институтов и заведующих выпускающими кафедрами о необходимости предоставления проектов учебных планов на автоматическую и содержательную экспертизу по ФГОС 3++ в срок до 25 октября 2026 г. Все проекты должны пройти валидацию без критических замечаний до передачи на визирование Проректору по УР.', 1);
INSERT INTO `announcements` (`id`, `title`, `category`, `publish_date`, `author_name`, `content`, `is_pinned`) VALUES (2, 'Регламент оформления служебных записок на корректировку учебных планов до начала семестра', 'Инструкция', '2026-09-28', 'Методический отдел АНОК', 'В соответствии с положением об образовательных программах, внесение изменений в утвержденный УП (перераспределение часов, замена форм контроля, смена обеспечивающей кафедры) допускается исключительно на основании двусторонне завизированной служебной записки (выпускающая + реализующая кафедры) с обязательным сохранением суммарного баланса 240 з.е.', 1);
INSERT INTO `announcements` (`id`, `title`, `category`, `publish_date`, `author_name`, `content`, `is_pinned`) VALUES (3, 'Заседание Ученого совета по утверждению актуализированных ОП и УП', 'Ученый совет', '2026-09-20', 'Секретариат Ученого совета', 'Очередное заседание Ученого совета университета по вопросу ежегодного утверждения учебных планов и ввода их в действие состоится 15 ноября 2026 года в зале заседаний Ректората.', 0);
INSERT INTO `announcements` (`id`, `title`, `category`, `publish_date`, `author_name`, `content`, `is_pinned`) VALUES (4, 'Обновление нормативной базы: изменения в требованиях к контактной работе ФГОС ВО 3++', 'ФГОС 3++', '2026-09-15', 'Экспертная группа АНОК', 'Опубликованы методические рекомендации Минобрнауки РФ по учету часов практической подготовки и контактной работы в электронной информационно-образовательной среде (ЭИОС).', 0);
