INSERT INTO `competencies` (`id`, `program_id`, `code`, `category`, `title`, `description`) VALUES (7, 1, 'УК-1', 'Универсальные', 'Системное и критическое мышление', 'Способен осуществлять поиск, критический анализ и синтез информации, применять системный подход для решения поставленных задач.');
INSERT INTO `competencies` (`id`, `program_id`, `code`, `category`, `title`, `description`) VALUES (8, 1, 'УК-2', 'Универсальные', 'Разработка и реализация проектов', 'Способен определять круг задач в рамках поставленной цели и выбирать оптимальные способы их решения, исходя из действующих правовых норм, имеющихся ресурсов и ограничений.');
INSERT INTO `competencies` (`id`, `program_id`, `code`, `category`, `title`, `description`) VALUES (9, 1, 'УК-3', 'Универсальные', 'Командная работа и лидерство', 'Способен осуществлять социальное взаимодействие и реализовывать свою роль в команде разработчиков программного обеспечения.');
INSERT INTO `competencies` (`id`, `program_id`, `code`, `category`, `title`, `description`) VALUES (10, 1, 'УК-4', 'Универсальные', 'Деловая коммуникация', 'Способен применять современные коммуникативные технологии на государственном языке РФ и иностранном(ых) языке(ах).');
INSERT INTO `competencies` (`id`, `program_id`, `code`, `category`, `title`, `description`) VALUES (11, 1, 'УК-8', 'Универсальные', 'Безопасность жизнедеятельности', 'Способен создавать и поддерживать в повседневной жизни и в профессиональной деятельности безопасные условия жизнедеятельности.');
INSERT INTO `competencies` (`id`, `program_id`, `code`, `category`, `title`, `description`) VALUES (12, 1, 'ОПК-1', 'Общепрофессиональные', 'Математический и естественнонаучный аппарат', 'Способен применять естественнонаучные и общеинженерные знания, методы математического анализа и моделирования в профессиональной деятельности.');
INSERT INTO `competencies` (`id`, `program_id`, `code`, `category`, `title`, `description`) VALUES (13, 1, 'ОПК-2', 'Общепрофессиональные', 'Информационно-коммуникационные технологии', 'Способен понимать принципы работы современных информационных технологий и программных средств, в том числе отечественного производства.');
INSERT INTO `competencies` (`id`, `program_id`, `code`, `category`, `title`, `description`) VALUES (14, 1, 'ОПК-4', 'Общепрофессиональные', 'Алгоритмы и структуры данных', 'Способен разрабатывать алгоритмы и программы, пригодные для практического применения в области информатики и вычислительной техники.');
INSERT INTO `competencies` (`id`, `program_id`, `code`, `category`, `title`, `description`) VALUES (15, 1, 'ОПК-6', 'Общепрофессиональные', 'Информационная безопасность', 'Способен разрабатывать и применять меры по обеспечению информационной безопасности и защиты данных вычислительных систем.');
INSERT INTO `competencies` (`id`, `program_id`, `code`, `category`, `title`, `description`) VALUES (16, 1, 'ПК-1', 'Профессиональные', 'Проектирование программных комплексов', 'Способен выполнять концептуальное, функциональное и логическое проектирование системного и прикладного программного обеспечения и баз данных.');
INSERT INTO `competencies` (`id`, `program_id`, `code`, `category`, `title`, `description`) VALUES (17, 1, 'ПК-2', 'Профессиональные', 'Разработка и отладка программного кода', 'Способен разрабатывать программные модули, интерфейсы и библиотеки на современных языках программирования с применением CI/CD.');
INSERT INTO `competencies` (`id`, `program_id`, `code`, `category`, `title`, `description`) VALUES (18, 1, 'ПК-3', 'Профессиональные', 'Тестирование и верификация ПО', 'Способен осуществлять интеграционное и модульное тестирование, профилирование и оптимизацию программного обеспечения.');
INSERT INTO `competencies` (`id`, `program_id`, `code`, `category`, `title`, `description`) VALUES (19, 1, 'ПК-4', 'Профессиональные', 'Сопровождение и администрирование систем', 'Способен осуществлять развертывание, конфигурирование и техническое сопровождение распределенных вычислительных систем и облачных платформ.');
